       CASE
         WHEN r.last_run_start IS NULL
              AND (COALESCE(cf.capture_floor_days, 0) < {{ param('lakeflow_stale_zombie_jobs', 'stale_days', 30) }}
                   OR j.create_time > dateadd(day, -{{ param('lakeflow_stale_zombie_jobs', 'stale_days', 30) }}, {{ audit_today() }}))
              THEN 'NOT_ASSESSED'
         WHEN r.last_run_start IS NULL THEN 'WARN'   -- confirmed no run in a long-enough capture window
         WHEN r.last_run_start < dateadd(day, -{{ param('lakeflow_stale_zombie_jobs', 'crit_stale_days', 90) }}, {{ audit_today() }}) THEN 'CRITICAL'
         WHEN r.last_run_start < dateadd(day, -{{ param('lakeflow_stale_zombie_jobs', 'stale_days', 30) }}, {{ audit_today() }}) THEN 'WARN'
         ELSE 'OK'
       END AS status,
       CASE
         WHEN r.last_run_start IS NULL
              AND (COALESCE(cf.capture_floor_days, 0) < {{ param('lakeflow_stale_zombie_jobs', 'stale_days', 30) }}
                   OR j.create_time > dateadd(day, -{{ param('lakeflow_stale_zombie_jobs', 'stale_days', 30) }}, {{ audit_today() }}))
